<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Acesso — ZystemWorkSpace</title><style>:root{font:15px system-ui;color:#e8eef7;background:#080d14}body{max-width:460px;margin:8vh auto;padding:18px}section{background:#101a28;border:1px solid #29405d;border-radius:14px;padding:22px}input,button{display:block;width:100%;box-sizing:border-box;padding:11px;margin:9px 0;border-radius:7px;border:1px solid #385474;background:#0b1420;color:#e8eef7}button{background:#1d4d78;cursor:pointer}.guest{background:#254d3e}.muted{color:#91a5bc}.msg{min-height:22px;color:#ffb1b1}a{color:#a9d5ff}</style></head><body><section><h1>ZystemWorkSpace</h1><p class="muted">Entre com usuário ou e-mail para salvar histórico, projetos e arquivos.</p><div id="msg" class="msg"></div><form id="login"><h2>Entrar</h2><input name="identifier" type="text" placeholder="Usuário ou e-mail" required><input name="password" type="password" placeholder="Senha" required><button>Entrar</button></form><hr><form id="register"><h2>Criar usuário</h2><input name="name" placeholder="Nome completo" required><input name="email" type="email" placeholder="E-mail" required><input name="password" type="password" minlength="8" placeholder="Senha — mínimo 8 caracteres" required><button>Cadastrar</button></form><button class="guest" id="guest">Continuar sem login — sessão temporária</button><p><a href="index.php">Voltar ao chat</a></p></section><script>const $=s=>document.querySelector(s),msg=$('#msg');async function send(data){msg.textContent='Aguarde...';try{const r=await fetch('../api/auth.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),d=await r.json();if(!d.ok)throw Error(d.error);location.href='index.php'}catch(e){msg.textContent=e.message}}$('#login').onsubmit=e=>{e.preventDefault();send({action:'login',identifier:e.target.identifier.value,password:e.target.password.value})};$('#register').onsubmit=e=>{e.preventDefault();send({action:'register',name:e.target.name.value,email:e.target.email.value,password:e.target.password.value})};$('#guest').onclick=()=>send({action:'guest'})</script></body></html>
